"""Fixture test, generated by `witness fixture` (Witness 0.1.0, relate-db 1.0.1).

The fixture is a 126-relationship graph pulled from Neo4j and shrunk until no single relationship could be removed
without changing this test's answer (126 of 126 change the answer). Run it with: pytest test_mex_foreign.py
"""

import json
from pathlib import Path

import relate

HERE = Path(__file__).parent
STATEMENT = "MATCH (:Airport {iata: 'MEX'})-[:HAS_ROUTE]->(b:Airport)-[:IN_COUNTRY]->(c:Country) WHERE c.code <> 'MX' RETURN count(DISTINCT b) AS foreign_airports, coll.sort(collect(DISTINCT c.code)) AS countries"
PARAMS = {}
EXPECTED = [{'foreign_airports': 63, 'countries': ['AR', 'BR', 'CA', 'CL', 'CN', 'CO', 'CR', 'CU', 'DE', 'DO', 'EC', 'ES', 'FR', 'GT', 'HN', 'JP', 'KR', 'NL', 'PA', 'PE', 'SV', 'UK', 'US', 'VE']}]


def test_mex_foreign_answer_on_the_fixture():
    db = relate.Database(str(HERE / "mex-foreign.rl"), read_only=True)
    try:
        res = db.execute(STATEMENT, PARAMS)
        rows = json.loads(json.dumps(res.data))
    finally:
        db.close()
    key = lambda r: json.dumps(r, sort_keys=True)  # noqa: E731
    assert sorted(rows, key=key) == sorted(EXPECTED, key=key)
